package main

import "fmt"

func main() {
	// Slice literal
	s := []int{1, 2, 3, 4, 5}
	fmt.Println("Slice:", s)
	fmt.Println("len:", len(s), "cap:", cap(s))

	// make
	m := make([]string, 3, 6)
	m[0] = "Go"
	m[1] = "is"
	m[2] = "fun"
	fmt.Println("Make slice:", m, "len:", len(m), "cap:", cap(m))

	// append
	var nums []int
	for i := 1; i <= 5; i++ {
		nums = append(nums, i*10)
		fmt.Printf("append %d: len=%d cap=%d\n", i*10, len(nums), cap(nums))
	}

	// nil vs empty slice
	var nilS []int
	emptyS := []int{}
	fmt.Println("nil slice == nil:", nilS == nil)
	fmt.Println("empty slice == nil:", emptyS == nil)

	// slice from array
	arr := [5]int{10, 20, 30, 40, 50}
	sl := arr[1:4]
	fmt.Println("Slice from array:", sl)
	sl[0] = 99
	fmt.Println("Array after modifying slice:", arr)
}
